import { and, count, desc, eq, gte, inArray, lt, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { activityEvents, getDb } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toActivityEvent } from "./_mappers";
import type { ActivityFilterInput } from "@/schemas/activity";
import type { ActivityEvent, ActivitySubjectKind } from "@/types/activity";
import type { IsoTimestamp, OrgId, Page } from "@/types/common";
import type { SQL } from "drizzle-orm";

/** Bounds used by the feed and the export. Both ends are inclusive. */
type ActivityQuery = Omit<ActivityFilterInput, "limit" | "cursor">;

/**
 * Canonicalises the window and refuses a range that ends before it starts.
 * ISO-8601 text sorts chronologically only after both ends share one format,
 * so a same-instant filter (`from === to`) still matches the stored stamp.
 */
function activityWindow(input: ActivityQuery): {
  since: IsoTimestamp | undefined;
  until: IsoTimestamp | undefined;
} {
  const since = input.since === undefined ? undefined : toIsoTimestamp(input.since);
  const until = input.until === undefined ? undefined : toIsoTimestamp(input.until);
  if (since !== undefined && until !== undefined && since > until) {
    throw new Error("Time range ends before it starts");
  }
  return { since, until };
}

function activityConditions(input: ActivityQuery): readonly SQL[] {
  const { since, until } = activityWindow(input);
  return compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
      ? undefined
      : eq(activityEvents.actorId, input.actorId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    input.subjectKind === undefined
      ? undefined
      : eq(activityEvents.subjectKind, input.subjectKind),
    since === undefined ? undefined : gte(activityEvents.occurredAt, since),
    until === undefined ? undefined : lte(activityEvents.occurredAt, until),
  );
}

