/**
 * One audit row per domain event. The actor and the time always come from the
 * envelope: the person who did the action, and when it happened, even when
 * this handler runs later (a catch-up job, for example).
 */
function on<K extends TaskflowEventType>(
  type: K,
  action: ActivityAction,
  facts: (
    payload: TaskflowEventPayload<K>,
  ) => ActivityFacts | Promise<ActivityFacts>,
): Unsubscribe {
  return subscribe(type, async (payload) => {
    const described = await facts(payload);
    await record(payload.orgId, action, {
      ...described,
      actorId: payload.actorId,
      occurredAt: payload.occurredAt,
    });
  });
}

